(function(){
  const api=window.CL_CONFIG.API_URL;const login=document.querySelector('#admin-login');const content=document.querySelector('#admin-content');const list=document.querySelector('#ticket-list');let token=sessionStorage.getItem('clAdminToken')||'';
  const esc=(v)=>String(v??'').replace(/[&<>'"]/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  async function request(path,options={}){const response=await fetch(`${api}${path}`,{...options,headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`,...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Erreur');return data}
  async function load(){const search=encodeURIComponent(document.querySelector('#ticket-search').value.trim());const status=document.querySelector('#ticket-filter').value;const data=await request(`/api/admin/tickets?search=${search}&status=${status}`);list.innerHTML=data.tickets.length?'':'<p>Aucun ticket.</p>';data.tickets.forEach((t)=>{const item=document.createElement('details');item.className='ticket';const history=(t.conversation||[]).map((m)=>`${m.role==='user'?'Utilisateur':'Assistant'} : ${m.content}`).join('\n\n');item.innerHTML=`<summary><strong>${esc(t.ticket_number)}</strong><span>${esc(t.summary)}</span><small>${esc(t.category)}</small><small>${esc(t.status)}</small></summary><div class="ticket-body"><p><b>${esc(t.name)}</b> · <a href="mailto:${esc(t.email)}">${esc(t.email)}</a> · Priorité ${esc(t.priority)}</p><p>${esc(t.description)}</p><pre>${esc(history||'Aucun historique')}</pre><div class="ticket-actions"><button data-status="OPEN">Ouvert</button><button data-status="IN_PROGRESS">En cours</button><button data-status="RESOLVED">Résolu</button><button class="delete">Supprimer les données</button></div></div>`;item.querySelectorAll('[data-status]').forEach((button)=>button.addEventListener('click',async()=>{await request(`/api/admin/tickets/${t.id}`,{method:'PATCH',body:JSON.stringify({status:button.dataset.status})});load()}));item.querySelector('.delete').addEventListener('click',async()=>{if(confirm(`Supprimer définitivement ${t.ticket_number} ?`)){await request(`/api/admin/tickets/${t.id}`,{method:'DELETE'});load()}});list.appendChild(item)});}
  login.addEventListener('submit',async(e)=>{e.preventDefault();token=document.querySelector('#admin-token').value;try{await load();sessionStorage.setItem('clAdminToken',token);login.hidden=true;content.hidden=false}catch(error){document.querySelector('#login-status').textContent=error.message}});
  document.querySelector('#refresh').addEventListener('click',load);document.querySelector('#ticket-filter').addEventListener('change',load);document.querySelector('#ticket-search').addEventListener('keydown',(e)=>{if(e.key==='Enter')load()});
  if(token){load().then(()=>{login.hidden=true;content.hidden=false}).catch(()=>sessionStorage.removeItem('clAdminToken'))}
})();
